import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { canonical, evaluateHumanPosture, fmt, parseTs, QUIET, type ClockFacts, type HumanState, type PostureConfig } from "./human-posture";
import { gate, policy, publicView, route, SOUND_CHANNELS, type Decision, type NoticeRouteInput } from "./interaction-policy";

// Golden fixtures generated by z0intelligence scripts/gen_human_posture_fixtures.py (SYNTHETIC, law C8).
// The Python twin must produce the same canonical JSON for every case (law C4).
const record = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const isState = (v: unknown): v is HumanState => record(v) && v.schema === "dash.human_state/v1" && record(v.anchors);
const isDecision = (v: unknown): v is Decision => record(v) && v.schema === "dash.interaction_decision/v1";
const isConfig = (v: unknown): v is PostureConfig => record(v) && typeof v.tz === "string";
const isFacts = (v: unknown): v is ClockFacts => record(v) && !("activity" in v);
const isNotice = (v: unknown): v is NoticeRouteInput => record(v);

const raw: unknown = JSON.parse(readFileSync(join(import.meta.dir, "fixtures/human-posture/cases.json"), "utf8"));
const cases = record(raw) && Array.isArray(raw.cases) ? raw.cases.filter(record) : [];
const WAKE = parseTs("2026-10-27T11:30:00Z"); // SYNTHETIC default wake 07:30 EDT
const at = (m: number) => fmt(WAKE + m * 60_000);
const decide = (m: number, facts: ClockFacts = {}, config: Partial<PostureConfig> = {}) =>
  policy(evaluateHumanPosture(facts, at(m), config), at(m));

describe("golden fixtures: TypeScript == Python (C4)", () => {
  test("fixtures loaded and synthetic", () => {
    expect(cases.length).toBeGreaterThan(100);
    expect(record(raw) && String(raw.note)).toContain("SYNTHETIC");
  });
  for (const c of cases) {
    const input = c.input;
    if (!record(input) || typeof c.name !== "string") continue;
    if (c.kind === "clock") {
      test(`clock: ${c.name}`, () => {
        if (!isFacts(input.facts) || !isConfig(input.config) || typeof input.now !== "string") throw new Error("bad case");
        expect(canonical(evaluateHumanPosture(input.facts, input.now, input.config))).toBe(canonical(c.expected));
      });
    } else if (c.kind === "policy") {
      test(`policy: ${c.name}`, () => {
        if (!isState(input.state) || typeof input.now !== "string") throw new Error("bad case");
        expect(canonical(policy(input.state, input.now))).toBe(canonical(c.expected));
      });
    } else if (c.kind === "route") {
      test(`route: ${c.name}`, () => {
        if (!isDecision(input.decision) || !isNotice(input.notice) || typeof input.now !== "string") throw new Error("bad case");
        expect(canonical(route(input.decision, input.notice, input.now))).toBe(canonical(c.expected));
      });
    }
  }
});

describe("laws, red then green", () => {
  test("C2: a decision after the freeze waits for the morning digest", () => {
    const d = decide(870);
    expect([d.phase, d.allowDecisions]).toEqual(["WIND_DOWN", "none"]);
    expect(route(d, { cls: "decision" }, at(870))).toMatchObject({ action: "digest", releaseAt: at(1470) });
  });
  test("C3: five decisions in PEAK: three delivered, two deferred", () => {
    const now = at(120);
    const counters = { hourKey: now.slice(0, 13), delivered: 0, blockStart: at(45), interrupts: 0 };
    const actions: string[] = [];
    for (let i = 0; i < 5; i++) {
      const d = policy(evaluateHumanPosture({ counters: { ...counters } }, now), now);
      const r = route(d, { cls: "decision" }, now);
      actions.push(r.action);
      if (r.action === "deliver") { counters.delivered++; counters.interrupts++; }
    }
    expect(actions).toEqual(["deliver", "deliver", "deliver", "defer", "defer"]);
  });
  test("C5: an agent's critical is a report", () => {
    expect(route(decide(1100), { cls: "critical", producer: "dash-notify", irreversible: true }, at(1100))).toMatchObject({ cls: "report", action: "digest" });
  });
  test("C5 + R2: an allowlisted critical at night needs the owner's opt-in", () => {
    const n = { cls: "critical", producer: "backup-guard", irreversible: true };
    expect(route(decide(1100), n, at(1100)).action).toBe("digest");
    expect(route(decide(1100, {}, { criticalOptIn: true }), n, at(1100)).action).toBe("deliver");
  });
  test("C10: done for today holds reports until the wake target", () => {
    for (const m of [510, 700, 900, 1100, 1435]) {
      const d = decide(m, { doneAt: at(500) });
      expect(QUIET.has(d.phase)).toBe(true);
      expect(route(d, { cls: "report" }, at(m)).action).toBe("digest");
    }
    expect(decide(1440, { doneAt: at(500) }).phase).toBe("INERTIA");
  });
  test("C14: only PEAK uses a channel that sounds", () => {
    for (let m = -30; m < 1440; m += 15) {
      const d = decide(m);
      expect(SOUND_CHANNELS.has(d.channel)).toBe(d.phase === "PEAK");
    }
  });
  test("C17: the repeated 01:00 on 2026-11-01 is continuous; an anchor in it takes the first occurrence", () => {
    const phases = ["2026-11-01T04:59:00Z", "2026-11-01T05:00:00Z", "2026-11-01T06:00:00Z", "2026-11-01T07:00:00Z"]
      .map((t) => policy(evaluateHumanPosture({}, t), t).phase);
    expect(phases).toEqual(["SLEEP", "SLEEP", "SLEEP", "SLEEP"]);
    const late = { bedTarget: "01:30" };
    expect(evaluateHumanPosture({}, "2026-11-01T05:00:00Z", late).anchors).toMatchObject({ bedTarget: "2026-11-01T05:30:00Z", freezeAt: "2026-11-01T02:00:00Z" });
    const seq = ["2026-11-01T05:29:00Z", "2026-11-01T05:30:00Z", "2026-11-01T06:30:00Z"].map((t) => policy(evaluateHumanPosture({}, t, late), t).phase);
    expect(seq).toEqual(["PRE_SLEEP", "SLEEP", "SLEEP"]);
  });
  test("C9/R5: clock-only state is default quality and never above the normal row", () => {
    const s = evaluateHumanPosture({}, at(120));
    expect([s.quality, s.readiness]).toEqual(["default", "unknown"]);
    expect(decide(120).interruptCapPerBlock).toBe(3);
  });
  test("R4: publicView is an allowlist", () => {
    expect(Object.keys(publicView(decide(120))).sort()).toEqual(["allowDecisions", "nextPeakAt"]);
  });
  test("gate: quiet phases never deliver a non-critical class", () => {
    for (const p of ["WIND_DOWN", "PRE_SLEEP", "SLEEP", "DISENGAGED"] as const)
      for (const c of ["decision", "report", "digest"] as const)
        for (const k of [true, false]) expect(gate(p, c, true, true, true, true, k)).toBe("digest");
  });
  test("C4: canonical refuses floats and sorts keys", () => {
    expect(() => canonical({ a: 1.5 })).toThrow();
    expect(canonical({ b: 1, a: { d: 2, c: 3 } })).toBe('{"a":{"c":3,"d":2},"b":1}');
  });
  test("C4: no clock, randomness or I/O in the pure twins", () => {
    for (const f of ["human-posture.ts", "interaction-policy.ts"]) {
      const src = readFileSync(join(import.meta.dir, f), "utf8");
      expect(src).not.toMatch(/Date\.now|new Date\(\)|Math\.random|process\.env|require\(|from "node:/);
    }
  });
});

describe("Bend twin", () => {
  // gate-table.txt is the output of z0intelligence bend/circadian/main.bend, whose laws are proven
  // in PROOF.bend: "<phase> <cls> <allowlisted> <irreversible> <optin> <plan> <capok> <action>".
  test("TypeScript gate == Bend gate on all 1024 inputs", () => {
    const rows = readFileSync(join(import.meta.dir, "fixtures/human-posture/gate-table.txt"), "utf8").trim().split("\n");
    expect(rows.length).toBe(1024);
    const phases = ["SLEEP", "INERTIA", "PEAK", "DIP", "SECOND", "WIND_DOWN", "PRE_SLEEP", "DISENGAGED"] as const;
    const classes = ["critical", "decision", "report", "digest"] as const;
    const actions = ["deliver", "defer", "digest"] as const;
    for (const row of rows) {
      const [p, c, a, i, o, t, k, act] = row.split(" ").map(Number);
      const phase = phases[p ?? -1], cls = classes[c ?? -1];
      if (!phase || !cls) throw new Error(`bad row ${row}`);
      expect(`${row} ${gate(phase, cls, a === 1, i === 1, o === 1, t === 1, k === 1)}`).toBe(`${row} ${actions[act ?? -1]}`);
    }
  });
});
